function Invoke-Guard {
 param([string]$Label,[string[]]$Vector,[string]$Expected,[string]$Output)
 $dir=Join-Path $guardRoot $Label;if(Test-Path $dir){throw "Refusing to overwrite guard evidence directory: $Label"};[IO.Directory]::CreateDirectory($dir)|Out-Null
 if($Vector.Count -ne 5 -or $Vector[3] -ne '-P' -or $Vector[4] -ne $producerScript){throw "Guard argv validation failed: $Label"}
 [IO.File]::WriteAllText((Join-Path $dir 'argv.json'),(@{executable=$cmake;workingDirectory=$dir;arguments=$Vector}|ConvertTo-Json -Depth 4),[Text.UTF8Encoding]::new($false))
 $psi=[Diagnostics.ProcessStartInfo]::new();$psi.FileName=$cmake;$psi.WorkingDirectory=$dir;$psi.UseShellExecute=$false;$psi.CreateNoWindow=$true;$psi.RedirectStandardOutput=$true;$psi.RedirectStandardError=$true;foreach($a in $Vector){[void]$psi.ArgumentList.Add($a)}
 $pr=[Diagnostics.Process]::new();$pr.StartInfo=$psi;$sw=[Diagnostics.Stopwatch]::StartNew();if(-not $pr.Start()){throw "Guard process did not start: $Label"};$ot=$pr.StandardOutput.ReadToEndAsync();$et=$pr.StandardError.ReadToEndAsync();$pr.WaitForExit();$exit=$pr.ExitCode;$sw.Stop();$out=$ot.GetAwaiter().GetResult();$err=$et.GetAwaiter().GetResult()
 [IO.File]::WriteAllText((Join-Path $dir 'stdout.log'),$out,[Text.UTF8Encoding]::new($false));[IO.File]::WriteAllText((Join-Path $dir 'stderr.log'),$err,[Text.UTF8Encoding]::new($false));$match=($out+"`n"+$err).Contains($Expected);$exists=Test-Path -LiteralPath $Output
 $r=[ordered]@{case=$Label;exitCode=$exit;elapsedSeconds=[Math]::Round($sw.Elapsed.TotalSeconds,3);expectedDiagnostic=$Expected;diagnosticMatched=$match;output=$Output;outputExists=$exists}
 [IO.File]::WriteAllText((Join-Path $dir 'result.json'),($r|ConvertTo-Json -Depth 4),[Text.UTF8Encoding]::new($false));if($exit -eq 0 -or !$match -or $exists){throw "Guard did not refuse cleanly: $Label, exit=$exit, match=$match, outputExists=$exists"};return [pscustomobject]$r
}
